select jsonb_build_object(
 'columns',(select jsonb_agg(x order by x) from(select c.relname||'|'||a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') x from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='mir_core' and c.relname in('account_preferences','help_faq','support_conversations','support_messages','support_attachments','chat_file_validations','conversations'))q),
 'constraints',(select jsonb_agg(x order by x) from(select c.relname||'|'||k.conname||'|'||pg_get_constraintdef(k.oid) x from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='mir_core' and c.relname in('account_preferences','help_faq','support_conversations','support_messages','support_attachments','chat_file_validations','conversations'))q),
 'indexes',(select jsonb_agg(schemaname||'|'||tablename||'|'||indexname||'|'||indexdef order by schemaname,tablename,indexname) from pg_indexes where schemaname='mir_core' and tablename in('account_preferences','help_faq','support_conversations','support_messages','support_attachments','chat_file_validations','conversations')),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname='mir_core' and c.relname in('account_preferences','help_faq','support_conversations','support_messages','support_attachments','chat_file_validations','conversations')),
 'tables',(select jsonb_agg(c.relname||'|rls='||c.relrowsecurity||'|acl='||coalesce(c.relacl::text,'') order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='mir_core' and c.relname in('account_preferences','help_faq','support_conversations','support_messages','support_attachments','chat_file_validations','conversations')),
 'functions',(select jsonb_agg(p.oid::regprocedure::text||'|def='||md5(pg_get_functiondef(p.oid))||'|src='||md5(p.prosrc)||'|sec='||p.prosecdef||'|cfg='||coalesce(p.proconfig::text,'')||'|acl='||coalesce(p.proacl::text,'') order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='mir_core' and p.proname in('support_staff','support_allowed','support_object_allowed','chat_file_gateway_catalog','chat_file_object_valid','chat_storage_object','chat_storage_upload')) or (n.nspname='public' and p.proname in('mir_help_faq','mir_account_preferences','mir_account_preferences_save','mir_client_center_snapshot','mir_client_support_action','mir_support_management_snapshot','mir_support_management_action','mir_help_faq_scoped','mir_client_center_snapshot_scoped','mir_client_support_action_scoped','mir_client_support_search_scoped','mir_chat_file_authorize','mir_chat_file_upload_authorize','mir_chat_file_record'))),
 'policies',(select jsonb_agg(policyname||'|'||cmd||'|'||permissive||'|'||roles::text||'|'||coalesce(qual,'')||'|'||coalesce(with_check,'') order by policyname) from pg_policies where schemaname='storage' and tablename='objects' and policyname in('mir_support_insert','mir_support_select','mir_support_delete','mir_chat_phase3a_insert','mir_chat_phase3a_select','mir_chat_phase3a_update','mir_chat_phase3a_delete')),
 'buckets',(select jsonb_agg(id||'|public='||public||'|limit='||coalesce(file_size_limit::text,'')||'|mimes='||coalesce(allowed_mime_types::text,'') order by id) from storage.buckets where id in('mir-internal','mir-support'))
) as snapshot;
